function villageView(){return `<div class="view-heading"><div><div class="eyebrow">Twoje królestwo · 1 osada</div><h1>Żelazny Gród</h1><p>Rozbuduj osadę, by zapewnić jej przyszłość.</p></div><div class="date-pill">⌂ &nbsp; Poziom osady <strong>${state.buildings.hall}</strong></div></div><div class="stat-row" style="margin:0 0 14px"><div class="stat"><div class="stat-icon">👥</div><div><b>${620+state.buildings.hall*85}</b><span>Mieszkańcy</span></div></div><div class="stat"><div class="stat-icon">🛠️</div><div><b>${Object.values(state.buildings).reduce((a,b)=>a+b,0)}</b><span>Барилга</span></div></div><div class="stat"><div class="stat-icon">⏳</div><div><b>+${18+state.buildings.hall*2}</b><span>Chwała / dzień</span></div></div><div class="stat"><div class="stat-icon">🛡️</div><div><b>${state.buildings.wall*120}</b><span>Obrona</span></div></div></div><div class="building-grid">${Object.entries(buildingMeta).map(([id,b])=>{let level=state.buildings[id],cost=b.cost.map((c,i)=>Math.ceil(c*(1+level*.38)));return `<article class="building"><div class="building-ico">${b.icon}</div><div class="building-main"><div class="building-top"><b>${b.name}</b><span class="level">POZ. ${level}</span></div><p>${b.desc}</p><div class="build-foot"><span class="cost">${cost[0]?`🪵 ${cost[0]} `:''}${cost[1]?`🪨 ${cost[1]} `:''}${cost[2]?`⚒ ${cost[2]}`:''}</span><button class="upgrade" onclick="upgradeBuilding('${id}')" ${canAfford(cost)?'':'disabled'}>Ulepsz&nbsp; ↗</button></div></div></article>`}).join('')}</div>`}
function canAfford(c){return state.resources.wood>=c[0]&&state.resources.stone>=c[1]&&state.resources.iron>=c[2]}
function armyView(){return `<div class="view-heading"><div><div class="eyebrow">Siła twojego królestwa</div><h1>Armia i szkolenie</h1><p>${armyTotal()} wojowników gotowych do służby.</p></div><div class="date-pill">⚔ &nbsp; Moc bojowa <strong>${armyPower()}</strong></div></div><div class="army-grid">${Object.entries(unitMeta).map(([id,u])=>`<article class="unit-card"><div class="unit-header"><div class="unit-icon">${u.icon}</div><div><b>${u.name}</b><small>Rekrutacja · Koszary poz. ${state.buildings.barracks}</small></div></div><div class="unit-count">${fmt(state.units[id])}</div><div class="unit-stats"><span>⚔ Atak ${u.atk}</span><span>🛡 Obrona ${u.def}</span></div><div class="cost" style="margin-bottom:8px">Koszt: 🪵${u.cost[0]} 🪨${u.cost[1]} ⚒${u.cost[2]} 🌾${u.cost[3]}</div><div class="recruit-controls"><input id="qty-${id}" type="number" min="1" max="99" value="5" aria-label="Liczba jednostek"><button onclick="recruit('${id}')">Zwerbuj</button></div></article>`).join('')}</div><section class="combat-card"><h3>⚑ &nbsp;Wyprawa w nieznane</h3><p>Wybierz cel i wyślij oddział. Zwiad odsłoni siłę przeciwnika, a zwycięstwo przyniesie łupy i chwałę.</p><div class="battle-row"><select id="target"><option value="north">Północny Bór · nieznane siły</option><option value="east">Kamienny Bród · nieznane siły</option><option value="south">Złote Łąki · nieznane siły</option><option value="west">Czarny Jar · 38 obrońców</option></select><button class="secondary" onclick="scout()">🦅 Zwiad</button><button class="primary" onclick="attack()">⚔ Wyrusz na wyprawę</button></div><div class="battle-log" id="battleLog"></div></section>`}
function armyPower(){return Object.entries(state.units).reduce((sum,[id,n])=>sum+n*unitMeta[id].atk,0)}
function councilView(){return `<div class="view-heading"><div><div class="eyebrow">Wspólna siła · Wspólna chwała</div><h1>Rada i sojusze</h1><p>Żadna korona nie jest wykuta w samotności.</p></div><div class="date-pill">♜ &nbsp; Sojusz <strong>Wataha Północy</strong></div></div><div class="council-grid"><article class="council-card"><div class="unit-icon">🐺</div><h3>Wataha Północy</h3><p>Sojusz zawiązany przez wodzów pogranicza. Razem kontrolujemy szlaki handlowe i bronimy swoich ziem.</p><div class="member-row"><b>Wielki Wódz</b><span>Ragnar · online</span></div><div class="member-row"><b>Wojownicy</b><span>12 członków</span></div><div class="member-row"><b>Pozycja</b><span>#8 w rankingu</span></div><button onclick="toast('Otworzono kanał sojuszu')">✉ &nbsp;Otwórz kanał</button></article><article class="council-card"><div class="unit-icon">🪙</div><h3>Wspólny skarbiec</h3><p>Wkład do skarbca pomaga rozwijać sojusz i odblokowywać premie dla wszystkich członków.</p><div class="member-row"><b>Skarbiec</b><span>12 480 🪙</span></div><div class="member-row"><b>Premia produkcji</b><span>+5% dla członków</span></div><button onclick="donate()">Wesprzyj sojusz · 100 drewna</button></article><article class="council-card"><div class="unit-icon">📯</div><h3>Wezwanie do walki</h3><p>Koordynuj natarcia i wspieraj sojuszników. Każda wspólna wygrana przynosi wszystkim chwałę.</p><div class="member-row"><b>Aktywne wezwania</b><span>2 wyprawy</span></div><div class="member-row"><b>Następny cel</b><span>Twierdza Czarnego Jaru</span></div><button onclick="toast('Wysłano sygnał do sojuszu')">⚑ &nbsp;Zgłoś gotowość</button></article><article class="council-card"><div class="unit-icon">🏆</div><h3>Tablica chwały</h3><p>Najznamienitsi władcy Marchii tego sezonu. Twoje zwycięstwa zapisują się w kronikach.</p><div class="member-row"><b>1. Ragnar Lodbrok</b><span>2 840 ✦</span></div><div class="member-row"><b>2. Freya z Klonu</b><span>2 210 ✦</span></div><div class="member-row"><b>18. Alarik</b><span>${state.points} ✦</span></div><button onclick="toast('Jesteś na dobrej drodze!')">Zobacz ranking →</button></article></div>`}
function questsView(){return `<div class="view-heading"><div><div class="eyebrow">Korona Północy · Twoje postępy</div><h1>Kronika zadań</h1><p>Wypełniaj cele, zdobywaj nagrody i zapisuj się w historii.</p></div><div class="date-pill">Nagrody sezonu <strong>620 / 1 000 ✦</strong></div></div><section class="panel" style="margin-bottom:13px"><div class="panel-head"><h2>✧ &nbsp;Droga władcy</h2><span class="eyebrow">Nagroda: 120 🪵 · 80 ⚒</span></div>${[['🏰','Rozbuduj dwór','Podnieś poziom serca osady.',state.quests.hall],['🦅','Poznaj sąsiednie ziemie','Wyślij zwiadowców na północ.',state.quests.scout],['⚔️','Wzmocnij szeregi',`Wyszkol co najmniej 50 żołnierzy (${armyTotal()}/50).`,armyTotal()>=50]].map((q,i)=>`<div class="quest"><div class="quest-icon">${q[0]}</div><div class="quest-copy"><b>${q[1]}</b><span>${q[2]}</span><div class="tiny-progress"><span style="width:${q[3]?100:i===2?Math.min(100,armyTotal()*2):i===0?60:0}%"></span></div></div><div class="quest-check ${q[3]?'done':''}">${q[3]?'✓':''}</div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>📜 &nbsp;Rozdziały sezonu</h2><span class="eyebrow">18 dni do końca</span></div><div class="member-row"><b>I. Pierwsze mury</b><span>Ukończono · +200 ✦</span></div><div class="member-row"><b>II. Sztandar nad Marchią</b><span>W toku · +400 ✦</span></div><div class="member-row"><b>III. Korona Północy</b><span>Zablokowane · +800 ✦</span></div></section>`}

