--- index.html
+++ index.html
@@ -65,4 +65,20 @@
 function armyView(){return `<div class="view-heading"><div><div class="eyebrow">Siła twojego królestwa</div><h1>Armia i szkolenie</h1><p>${armyTotal()} wojowników gotowych do służby.</p></div><div class="date-pill">⚔ &nbsp; Moc bojowa <strong>${armyPower()}</strong></div></div><div class="army-grid">${Object.entries(unitMeta).map(([id,u])=>`<article class="unit-card"><div class="unit-header"><div class="unit-icon">${u.icon}</div><div><b>${u.name}</b><small>Rekrutacja · Koszary poz. ${state.buildings.barracks}</small></div></div><div class="unit-count">${fmt(state.units[id])}</div><div class="unit-stats"><span>⚔ Atak ${u.atk}</span><span>🛡 Obrona ${u.def}</span></div><div class="cost" style="margin-bottom:8px">Koszt: 🪵${u.cost[0]} 🪨${u.cost[1]} ⚒${u.cost[2]} 🌾${u.cost[3]}</div><div class="recruit-controls"><input id="qty-${id}" type="number" min="1" max="99" value="5" aria-label="Liczba jednostek"><button onclick="recruit('${id}')">Zwerbuj</button></div></article>`).join('')}</div><section class="combat-card"><h3>⚑ &nbsp;Wyprawa w nieznane</h3><p>Wybierz cel i wyślij oddział. Zwiad odsłoni siłę przeciwnika, a zwycięstwo przyniesie łupy i chwałę.</p><div class="battle-row"><select id="target"><option value="north">Północny Bór · nieznane siły</option><option value="east">Kamienny Bród · nieznane siły</option><option value="south">Złote Łąki · nieznane siły</option><option value="west">Czarny Jar · 38 obrońców</option></select><button class="secondary" onclick="scout()">🦅 Zwiad</button><button class="primary" onclick="attack()">⚔ Wyrusz na wyprawę</button></div><div class="battle-log" id="battleLog"></div></section>`}
 function armyPower(){return Object.entries(state.units).reduce((sum,[id,n])=>sum+n*unitMeta[id].atk,0)}
 function councilView(){return `<div class="view-heading"><div><div class="eyebrow">Wspólna siła · Wspólna chwała</div><h1>Rada i sojusze</h1><p>Żadna korona nie jest wykuta w samotności.</p></div><div class="date-pill">♜ &nbsp; Sojusz <strong>Wataha Północy</strong></div></div><div class="council-grid"><article class="council-card"><div class="unit-icon">🐺</div><h3>Wataha Północy</h3><p>Sojusz zawiązany przez wodzów pogranicza. Razem kontrolujemy szlaki handlowe i bronimy swoich ziem.</p><div class="member-row"><b>Wielki Wódz</b><span>Ragnar · online</span></div><div class="member-row"><b>Wojownicy</b><span>12 członków</span></div><div class="member-row"><b>Pozycja</b><span>#8 w rankingu</span></div><button onclick="toast('Otworzono kanał sojuszu')">✉ &nbsp;Otwórz kanał</button></article><article class="council-card"><div class="unit-icon">🪙</div><h3>Wspólny skarbiec</h3><p>Wkład do skarbca pomaga rozwijać sojusz i odblokowywać premie dla wszystkich członków.</p><div class="member-row"><b>Skarbiec</b><span>12 480 🪙</span></div><div class="member-row"><b>Premia produkcji</b><span>+5% dla członków</span></div><button onclick="donate()">Wesprzyj sojusz · 100 drewna</button></article><article class="council-card"><div class="unit-icon">📯</div><h3>Wezwanie do walki</h3><p>Koordynuj natarcia i wspieraj sojuszników. Każda wspólna wygrana przynosi wszystkim chwałę.</p><div class="member-row"><b>Aktywne wezwania</b><span>2 wyprawy</span></div><div class="member-row"><b>Następny cel</b><span>Twierdza Czarnego Jaru</span></div><button onclick="toast('Wysłano sygnał do sojuszu')">⚑ &nbsp;Zgłoś gotowość</button></article><article class="council-card"><div class="unit-icon">🏆</div><h3>Tablica chwały</h3><p>Najznamienitsi władcy Marchii tego sezonu. Twoje zwycięstwa zapisują się w kronikach.</p><div class="member-row"><b>1. Ragnar Lodbrok</b><span>2 840 ✦</span></div><div class="member-row"><b>2. Freya z Klonu</b><span>2 210 ✦</span></div><div class="member-row"><b>18. Alarik</b><span>${state.points} ✦</span></div><button onclick="toast('Jesteś na dobrej drodze!')">Zobacz ranking →</button></article></div>`}
 function questsView(){return `<div class="view-heading"><div><div class="eyebrow">Korona Północy · Twoje postępy</div><h1>Kronika zadań</h1><p>Wypełniaj cele, zdobywaj nagrody i zapisuj się w historii.</p></div><div class="date-pill">Nagrody sezonu <strong>620 / 1 000 ✦</strong></div></div><section class="panel" style="margin-bottom:13px"><div class="panel-head"><h2>✧ &nbsp;Droga władcy</h2><span class="eyebrow">Nagroda: 120 🪵 · 80 ⚒</span></div>${[['🏰','Rozbuduj dwór','Podnieś poziom serca osady.',state.quests.hall],['🦅','Poznaj sąsiednie ziemie','Wyślij zwiadowców na północ.',state.quests.scout],['⚔️','Wzmocnij szeregi',`Wyszkol co najmniej 50 żołnierzy (${armyTotal()}/50).`,armyTotal()>=50]].map((q,i)=>`<div class="quest"><div class="quest-icon">${q[0]}</div><div class="quest-copy"><b>${q[1]}</b><span>${q[2]}</span><div class="tiny-progress"><span style="width:${q[3]?100:i===2?Math.min(100,armyTotal()*2):i===0?60:0}%"></span></div></div><div class="quest-check ${q[3]?'done':''}">${q[3]?'✓':''}</div></div>`).join('')}</section><section class="panel"><div class="panel-head"><h2>📜 &nbsp;Rozdziały sezonu</h2><span class="eyebrow">18 dni do końca</span></div><div class="member-row"><b>I. Pierwsze mury</b><span>Ukończono · +200 ✦</span></div><div class="member-row"><b>II. Sztandar nad Marchią</b><span>W toku · +400 ✦</span></div><div class="member-row"><b>III. Korona Północy</b><span>Zablokowane · +800 ✦</span></div></section>`}
+function setView(view){state.view=view;document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===view));render();save()}
+function render(){const views={map:mapView,village:villageView,army:armyView,council:councilView,quests:questsView};document.getElementById('main').innerHTML=(views[state.view]||mapView)();document.getElementById('rightcol').innerHTML=sidePanels();renderResources();document.querySelectorAll('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view))}
+function toast(msg){let t=document.getElementById('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2300)}
+function spend(cost){if(!canAfford(cost))return false;state.resources.wood-=cost[0];state.resources.stone-=cost[1];state.resources.iron-=cost[2];return true}
+function upgradeBuilding(id){let b=buildingMeta[id],lvl=state.buildings[id],cost=b.cost.map(c=>Math.ceil(c*(1+lvl*.38)));if(!spend(cost)){toast('Brakuje surowców');return}state.buildings[id]++;state.points+=25;if(id==='hall')state.quests.hall=true;state.logs.unshift(`${b.name} rozbudowany do poziomu ${state.buildings[id]}.`);toast(`${b.name} rozbudowany! +25 chwały`);save();render()}
+function recruit(id){let amount=Math.max(1,Math.min(99,parseInt(document.getElementById(`qty-${id}`)?.value)||1)),c=unitMeta[id].cost.map(n=>n*amount);if(state.resources.wood<c[0]||state.resources.stone<c[1]||state.resources.iron<c[2]||state.resources.food<c[3]){toast('Brakuje surowców na rekrutację');return}state.resources.wood-=c[0];state.resources.stone-=c[1];state.resources.iron-=c[2];state.resources.food-=c[3];state.units[id]+=amount;state.logs.unshift(`Do armii dołączyło ${amount} ${unitMeta[id].name.toLowerCase()}(ów).`);toast(`Wyszkolono ${amount} · ${unitMeta[id].name}`);save();render()}
+function scout(){let target=document.getElementById('target')?.value||'north';let names={north:'Północny Bór',east:'Kamienny Bród',south:'Złote Łąki',west:'Czarny Jar'};if(state.units.scout<1){toast('Potrzebujesz zwiadowcy');return}state.units.scout--;state.quests.scout=true;let force=target==='west'?38:target==='north'?24:target==='east'?31:18;state.logs.unshift(`Zwiadowcy donoszą: ${names[target]} — około ${force} obrońców.`);state.points+=10;save();let log=document.getElementById('battleLog');log.style.display='block';log.innerHTML=`🦅 <b>Wieści z ${names[target]}</b><br>Wyprawa zwiadowcza rozpoznała teren. Oceniana siła obrońców: <b>${force} wojowników</b>. Zyskano 10 chwały.`;toast('Zwiad zakończony · +10 chwały');renderResources()}
+function attack(){let target=document.getElementById('target')?.value||'north';let names={north:'Północny Bór',east:'Kamienny Bród',south:'Złote Łąki',west:'Czarny Jar'};if(state.territories[target]==='owned'){toast('Ta prowincja już należy do ciebie');return}let force=target==='west'?125:target==='north'?65:target==='east'?95:52;let power=armyPower();if(power<force){let loss=Math.max(1,Math.floor(armyTotal()*.08));for(let id in state.units)state.units[id]=Math.max(0,state.units[id]-Math.ceil(loss*state.units[id]/Math.max(1,armyTotal())));state.logs.unshift(`Wyprawa na ${names[target]} odparta. Armia wycofała się.`);let log=document.getElementById('battleLog');log.style.display='block';log.innerHTML=`🩸 <b>Porażka pod ${names[target]}</b><br>Siła twojej armii (${power}) nie wystarczyła przeciw ${force} obrońcom. Stracono część wojowników. Wzmocnij szeregi i spróbuj ponownie.`;toast('Wyprawa odparta — wzmocnij armię');save();renderResources();return}let losses=Math.max(1,Math.floor(armyTotal()*(.08+force/(power*4))));let left=armyTotal();for(let id in state.units){let n=state.units[id];state.units[id]=Math.max(0,n-Math.ceil(losses*n/Math.max(1,left)))}state.territories[target]='owned';state.points+=100;state.resources.wood+=180;state.resources.stone+=120;state.resources.food+=150;state.logs.unshift(`Zwycięstwo! ${names[target]} pod twoim sztandarem. +100 chwały.`);let log=document.getElementById('battleLog');log.style.display='block';log.innerHTML=`🏆 <b>Zwycięstwo pod ${names[target]}!</b><br>Twoi wojownicy przełamali obronę (${power} vs ${force}). Prowincja należy do ciebie. Zdobycze: 🪵 180 · 🪨 120 · 🌾 150 · ✦ 100. Straty: około ${losses} żołnierzy.`;toast(`Zwycięstwo! ${names[target]} zdobyty · +100 chwały`);save();renderResources()}
+function donate(){if(state.resources.wood<100){toast('Brakuje 100 drewna');return}state.resources.wood-=100;state.points+=15;state.logs.unshift('Wsparłeś skarbiec sojuszu. +15 chwały.');toast('Dar dla sojuszu przekazany · +15 chwały');save();render()}
+function selectRegion(id){if(id==='home'){toast('To twoja stolica — Żelazny Gród');return}let names={north:'Północny Bór',east:'Kamienny Bród',south:'Złote Łąki',west:'Czarny Jar'},enemy=id==='west',owned=state.territories[id]==='owned';let backdrop=document.getElementById('modal');backdrop.innerHTML=`<div class="modal"><div class="eyebrow">Prowincja · Marchie Północy</div><h2>${names[id]}</h2><p>${owned?'Ta prowincja jest pod twoim sztandarem. Jej zasoby wspierają rozwój królestwa.':enemy?'Wrogi klan umocnił się w tym jarze. Ich obrońcy nie oddadzą ziemi bez walki.':'Nieodkryte tereny kryją surowce, nowe szlaki i niebezpieczeństwa. Wyślij zwiadowców, zanim ruszysz do ataku.'}</p><div class="member-row"><b>Status</b><span>${owned?'Twoja prowincja':enemy?'Terytorium wroga':'Nieznane'}</span></div><div class="member-row"><b>Możliwa zdobycz</b><span>🪵 180 · 🪨 120 · ✦ 100</span></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Zamknij</button>${!owned?`<button class="primary" onclick="closeModal();setView('army');document.getElementById('target').value='${id}'">⚔ Przygotuj wyprawę</button>`:''}</div></div>`;backdrop.classList.add('open')}
+function closeModal(){document.getElementById('modal').classList.remove('open')}
+document.getElementById('modal').addEventListener('click',e=>{if(e.target.id==='modal')closeModal()});document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));
+accrue();render();save();setInterval(()=>{accrue();renderResources();save()},1000);
