 function selectRegion(id){if(id==='home'){toast('To twoja stolica — Żelazny Gród');return}let names={north:'Północny Bór',east:'Kamienny Bród',south:'Złote Łąki',west:'Czarny Jar'},enemy=id==='west',owned=state.territories[id]==='owned';let backdrop=document.getElementById('modal');backdrop.innerHTML=`<div class="modal"><div class="eyebrow">Prowincja · Marchie Północy</div><h2>${names[id]}</h2><p>${owned?'Ta prowincja jest pod twoim sztandarem. Jej zasoby wspierają rozwój królestwa.':enemy?'Wrogi klan umocnił się w tym jarze. Ich obrońcy nie oddadzą ziemi bez walki.':'Nieodkryte tereny kryją surowce, nowe szlaki i niebezpieczeństwa. Wyślij zwiadowców, zanim ruszysz do ataku.'}</p><div class="member-row"><b>Status</b><span>${owned?'Twoja prowincja':enemy?'Terytorium wroga':'Nieznane'}</span></div><div class="member-row"><b>Możliwa zdobycz</b><span>🪵 180 · 🪨 120 · ✦ 100</span></div><div class="modal-actions"><button class="secondary" onclick="closeModal()">Zamknij</button>${!owned?`<button class="primary" onclick="closeModal();setView('army');document.getElementById('target').value='${id}'">⚔ Przygotuj wyprawę</button>`:''}</div></div>`;backdrop.classList.add('open')}
